const raw = $input.first().json.response || '';
let classification;
try {
  const match = raw.match(/\{[\s\S]*\}/);
  classification = JSON.parse(match ? match[0] : raw);
} catch(e) {
  classification = {
    category: 'OTHER',
    urgency: 'medium',
    sentiment: 'neutral',
    confidence: 0.3,
    summary: 'Classification echouee'
  };
}
const validCategories = ['ORDER_STATUS','RETURN_REQUEST','PRODUCT_QUESTION','COMPLAINT','SHIPPING','BILLING','SPAM','OTHER'];
const validUrgency = ['low','medium','high','critical'];
const validSentiment = ['positive','neutral','negative','angry'];
if (!validCategories.includes(classification.category)) classification.category = 'OTHER';
if (!validUrgency.includes(classification.urgency)) classification.urgency = 'medium';
if (!validSentiment.includes(classification.sentiment)) classification.sentiment = 'neutral';
classification.confidence = Math.max(0, Math.min(1, Number(classification.confidence) || 0.5));
const emailId = $('Get Email').first().json?.id || null;
return [{ json: { emailId, classification } }];

const d = $input.first().json;
const c = d.classification;
const emailId = d.emailId;
const summary = (c.summary||'').replace(/'/g,"''").substring(0,200);
const from_addr = $('Normalize Email').first().json.from_addr;

// Build update SQL
let update_sql = `UPDATE mail_queue SET category = '${c.category}', urgency = '${c.urgency}', sentiment = '${c.sentiment}', confidence = ${c.confidence}, status = 'PENDING', processed_at = NOW() WHERE id = ${emailId};`;

// Build action SQL based on classification
let action_sql = '';
let route = 'normal';
if (c.urgency === 'critical') {
  route = 'critical';
  action_sql = `INSERT INTO alerts (store_id, type, severity, message, is_read, is_sent, created_at) VALUES (1, 'EMAIL_CRITICAL', 'critical', 'Email critique: ${summary}', false, false, NOW());`;
} else if (c.category === 'SPAM') {
  route = 'spam';
  action_sql = `UPDATE mail_queue SET status = 'REJECTED' WHERE id = ${emailId};`;
} else if (c.category === 'COMPLAINT') {
  route = 'complaint';
  action_sql = `INSERT INTO sav_requests (store_id, type, status, description, request_number, created_at) VALUES (1, 'COMPLAINT', 'open', '${summary}', 'SAV-EMAIL-' || to_char(NOW(), 'YYYYMMDDHH24MISS'), NOW());`;
}

return [{ json: { emailId, classification: c, route, update_sql, action_sql } }];
